"""Rotate old entries from app.log to archive.log.

Usage: python rotate.py AS_OF

Where AS_OF is a Unix timestamp in integer seconds. Every entry in app.log
whose timestamp is strictly older than 7 days before AS_OF is moved to
archive.log. Remaining entries are rewritten to app.log in original order.
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # 7 days before AS_OF

    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None and dt.timestamp() < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Append archived entries to archive.log
    if archive:
        with open("archive.log", "a") as f:
            f.writelines(archive)

    # Rewrite app.log with remaining entries
    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

